--[[
	Midnight Helper — Mexican-Spanish overlay (esMX).
	Mexican clients get the esES pack (Locale.lua aliases esMX -> esES). The esMX client names many game things
	differently (measured 11 Oct 2026 in Blizzard data, wago build 12.1.0.69933): Delve = abismo, dungeon = calabozo,
	Great Vault = Gran bóveda, Renown = Reconocimiento, Bountiful = abundante, Mítico, tropa, Se busca surcabismos …
	This file only runs on an esMX client and overwrites just those esES lines. Loads after every other Locales file.
	Written by the build chat's helpers, not reviewed by a native speaker.
]]

local _, ns = ...

if GetLocale() ~= "esMX" then
	return
end
local es = ns._mhLocales and ns._mhLocales.esES
if not es then
	return
end

for k, v in pairs({
	ABOUT_WINDOW_BODY = "Autores: TwelveInchy & Claude\n\nTu compañero todo en uno de Midnight, organizado en cuatro salas — Me, Codex, Tools y Settings. Fija favoritos bajo la barra de búsqueda y escribe para saltar a cualquier sitio. Incluye Esta semana, Abismos & Bóveda, coaches de Abismos y Rituales, el asesor de Encantamientos y Gemas, instantánea de cuenta, guías del Codex, profesiones y herramientas integradas — EN / NL / DE / FR / ES / PT / IT.\n\nGracias a los addons y guías con los que comprobamos nuestros datos: DBM (habilidades de jefes e ID de hechizos), HandyNotes_Midnight (ubicaciones de raros y tesoros), GTFO (ID de hechizos de peligros), RareScanner (manejo de viñetas) y Wowhead, Icy Veins, Method y wowcarry. Tomamos los ID y los números como pistas y los comprobamos en el propio juego siempre que podemos; no usamos código de estos addons.",
	ACADEMY_CHAT_HINT = "Haz clic en una línea (o en su icono de copiar) y pulsa Ctrl+C. Pulsa Intro: el chat se abre en Decir, que solo ve la gente cerca de ti. Para tu grupo, escribe primero /p y un espacio; en un calabozo del Buscador de grupos, escribe /i. Luego Ctrl+V para pegar e Intro para enviar. Pon el nombre del hechizo del enemigo donde dice [nombre del hechizo].",
	ACADEMY_DPS_BOTH_BODY = "Ya conoces los combates desde el asiento de DPS, y eso es la mayor parte del trabajo. Tanquear te da colas de calabozo instantáneas; sanar es lo que más nervios exige, pero es lo más buscado.\n\nPrueba el rol nuevo primero en un abismo o en un Follower Dungeon, donde nadie depende de ti. Luego mantén un rol como principal durante una temporada en vez de cambiar en cada pug.",
	ACADEMY_DPS_PRACTICE_BODY = "Pega a un muñeco de entrenamiento durante dos minutos: mantén tu recurso en movimiento, encadena tus cooldowns y fíjate en qué se te cae.\n\nDespués, abismos; luego, calabozos Normal. No necesitas una rotación perfecta para empezar: necesitas seguir pulsando y seguir vivo.",
	ACADEMY_HEAL_BOTH_BODY = "La pista de DPS es el segundo rol más suave: solo tus teclas, tus interrupciones y dónde te colocas, sin presión sobre el grupo. Como tanque esperas menos que nadie para un grupo de calabozo, en cuanto tanquear te dé menos miedo.\n\nDos roles en una semana con grupos de desconocidos es mucho; elige uno como \"principal\" para tener menos miedo.",
	ACADEMY_HEAL_DUNGEON_TITLE = "Tu primer calabozo normal (después de uno con seguidores)",
	ACADEMY_HEAL_LADDER_BODY = "1. Sana a un amigo fuera, en el mundo (no en un calabozo)\n2. Abismos con un grupo pequeño\n3. Calabozo con seguidores: unos PNJ completan el grupo (nivel 80-90). Buscador de grupos -> Buscador de calabozos -> Calabozos con seguidores\n4. Calabozo normal con amigos pacientes\n5. Banda LFR / en Heroico cuando estés listo\n\nLos abismos son el paso más suave hacia el contenido instanciado.",
	ACADEMY_HEAL_WHAT_BODY = "Un sanador mantiene vivo al grupo. Los enemigos hieren a tus amigos; tus sanaciones les devuelven la salud.\n\nCómo eliges a quién sanas: haz clic en la barra de esa persona (su marco) y pulsa tu sanación. ¿Nadie seleccionado, o un enemigo seleccionado? Entonces una sanación normal cae sobre ti. Los hechizos que también pueden dañar a enemigos (como Choque Sagrado y Estrago divino) van entonces al enemigo.\n\nLos marcos son las barras de salud de tu grupo en la pantalla. Más fáciles de leer: Esc -> Modo de edición -> haz clic en Marcos de grupo -> marca \"Usar marcos de grupo estilo banda\".\n\nSiguiente paso, cuando hacer clic te resulte fácil: Lanzamiento con clic. Pones una sanación en un clic del ratón, y un clic en un marco sana a esa persona al momento. Esc -> Opciones -> Experiencia de juego -> Atajos de teclado -> Lanzamiento con clic, luego \"Añadir atajo\" y \"Guardar\". ¿Usas los marcos de un addon con su propio lanzamiento con clic (DandersFrames, Cell, VuhDo)? Entonces pon ahí tus sanaciones y deja vacío el Lanzamiento con clic de Blizzard: dos en el mismo clic se estorban.\n\nEquipo: la estadística principal de tu especialización de sanador (en los sanadores: Intelecto). El juego la muestra bajo cada especialización como \"Estadística principal\".\n\nPara pasar a tu especialización de sanador: Talentos y libro de hechizos -> Especialización -> Activar (gratis). Especialización de botín, es decir, para qué especialización recibes botín: clic derecho en tu propio retrato (la imagen de tu personaje junto a tu barra de salud) -> Especialización de botín.",
	ACADEMY_STEP_FOLLOWER = "Un calabozo con seguidores hecho (Buscador de grupos, abajo a la derecha -> Buscador de calabozos -> Calabozos con seguidores)",
	ACADEMY_STEP_HEAL_FRAMES = "\"Usar marcos de grupo estilo banda\" activado (Esc -> Modo de edición -> Marcos de grupo)",
	ACADEMY_STEP_HEAL_GEAR = "Equipo con Intelecto, la estadística principal de toda especialización de sanador (Talentos y libro de hechizos -> Especialización la muestra como \"Estadística principal\"). Sobre todo un arma con Intelecto. Un Paladín conserva sus placas: hay placas con Intelecto. ¿Dónde? Apúntate como Daño, con tu Especialización de botín en tu especialización de sanador (clic derecho en tu retrato). Los calabozos pueden darte entonces equipo con Intelecto, pero qué objeto te toca no es seguro. Después vuelve a ponerla en \"Especialización actual\".",
	ACADEMY_STEP_NORMAL = "Un calabozo normal hecho con jugadores reales: con amigos o tu hermandad si puedes, si no con un grupo aleatorio. Invita antes a tus amigos (clic derecho en su nombre en el chat -> Invitar, o escribe /inv y su nombre). Luego Buscador de grupos -> Buscador de calabozos -> un calabozo aleatorio, marca el icono de Tanque o Sanador y pulsa \"Buscar grupo\" (en un grupo lo pulsa el líder). ¿No eres el líder? Marca tú tu rol antes en el Buscador de calabozos, o espera: cuando el líder pulse \"Buscar grupo\", te sale \"Confirma tu función:\" - marca tu rol y haz clic en \"Aceptar\"",
	ACADEMY_STEP_TANK_GEAR = "Equipo con la estadística principal de tu especialización de tanque (Paladín y Guerrero Protección: también un escudo). Talentos y libro de hechizos -> Especialización la muestra bajo cada especialización como \"Estadística principal\"; tu ventana de personaje solo muestra la estadística principal de la especialización en la que estás. ¿Aún sin escudo? A nivel 90: Casa de Subastas -> Armadura -> Miscelánea -> Escudo, y además un arma de una mano con tu estadística principal (un arma de dos manos no va con un escudo). Por debajo de nivel 90: apúntate como Daño, con tu Especialización de botín en tu especialización de tanque (clic derecho en tu retrato). Los calabozos pueden darte entonces equipo de tanque, también un escudo, pero no es seguro. Después vuelve a ponerla en \"Especialización actual\".",
	ACADEMY_SUBTITLE = "Un curso corto de tanquear, sanar y hacer DPS en grupo: cómo pensar, qué preparar primero y un camino tranquilo hacia los calabozos.",
	ACADEMY_TANK_BOTH_BODY = "La pista de DPS es el segundo rol más suave: tus teclas, tus interrupciones y dónde te colocas, sin un grupo que dependa de ti. Sanar es el salto más grande, pero ya sabes leer los pulls, y eso es la mitad.\n\nElige un rol principal en calabozos durante un tiempo y practica el otro en abismos o fuera, en el mundo. Cambiar de rol en el mismo grupo de M+ con desconocidos duplica el estrés; dominar primero un rol da confianza para el segundo.",
	ACADEMY_TANK_DUNGEON_TITLE = "Tu primer calabozo normal (después de uno con seguidores)",
	ACADEMY_TANK_LADDER_BODY = "1. Élites (enemigos más fuertes) fuera, en el mundo, con un amigo\n2. Abismos (instancia más pequeña - pestaña Abismos)\n3. Calabozo con seguidores: unos PNJ completan el grupo (nivel 80-90). Buscador de grupos -> Buscador de calabozos -> Calabozos con seguidores\n4. Calabozo normal con gente en la que confías\n5. Heroico / LFR cuando te sientas cómodo\n\nQuédate en cada paso hasta que te parezca aburrido, no aterrador. Luego sube al siguiente.",
	ACADEMY_TANK_RAID_BODY = "El LFR es la entrada suave a las bandas: perdona mucho y hay muchos sanadores. Fíjate en los ataques grandes del jefe y en estar en el sitio correcto.\n\nTanquear en banda en Mítico no es el siguiente paso: primero siéntete cómodo en Heroico/LFR.",
	ACADEMY_WORDS_BODY = "Pull: empezar un combate contra un pack.\nPack: un grupo de enemigos que luchan juntos.\nTrash: los enemigos normales entre los jefes.\nJefe (boss): un enemigo grande y fuerte, con sus propios trucos.\nAggro: un enemigo te está atacando.\nAmenaza (threat): lo enfadado que está un enemigo contigo. Ataca a quien tiene más.\nProvocar (taunt): una tecla de tanque que obliga a un enemigo a atacarte.\nCooldown: la espera antes de poder pulsar una tecla otra vez. \"(1.5 min)\" detrás de una tecla es esa espera.\nOn cooldown (como en \"púlsalo on cooldown\"): vuelve a pulsarlo en cuanto esté listo.\nDefensiva: una tecla con la que recibes menos daño durante un rato.\nMitigación activa: una tecla de tanque que pulsas una y otra vez para recibir menos daño. En el kit de tanque, [Bloqueo] marca una tecla de este tipo que usa tu escudo.\nInterrumpir (kick): una tecla que detiene el hechizo de un enemigo mientras lo lanza.\nCC (control): sacar a un enemigo del combate un rato, por ejemplo con un aturdimiento.\nDebuff: un efecto malo sobre alguien, como un veneno.\nDisipar (dispel): quitarle un debuff a alguien.\nWipe: muere todo el grupo. Vuelven corriendo y lo intentan otra vez.\nOOM: out of mana, sin maná. Un sanador sin maná no puede sanar.\nMarcos (frames): las barras de salud de tu grupo en la pantalla.\nDPS: los jugadores que hacen el daño (en el Buscador de grupos ese rol se llama Daño). También significa daño por segundo.\nEspecialización (spec): el camino que eliges dentro de tu clase, como Sagrado, Protección o Reprensión en un paladín.\nHP (salud): tus puntos de vida. A 0 mueres.\nBuff: un efecto bueno sobre alguien, como más estadísticas o una sanación que sigue curando. Tus propios buffs salen como iconos arriba a la derecha.\nNormal, Heroico, Mítico: lo difícil que es un calabozo o una banda, de fácil a difícil.\nLFR (Buscador de bandas): la forma más fácil de hacer bandas. Apúntate en el Buscador de grupos -> Calabozos y bandas -> Buscador de bandas.\nM+ (Mythic+): un calabozo mítico con una piedra angular. Juegan contra un temporizador, y cada nivel + hace más fuertes a los enemigos.\nCalabozo con seguidores (follower dungeon): un calabozo en el que personajes del ordenador (PNJ) completan tu grupo.\nMuñeco de entrenamiento: un blanco de práctica en la ciudad que nunca muere. Golpéalo para practicar tus teclas.\nEquipo (gear): la armadura y las armas que llevas.\nLanzamiento (cast): un hechizo que tarda un momento: primero se llena una barra. Instantáneo: un hechizo que funciona al momento.\nHoT (sanación en el tiempo): una sanación que sigue curando un rato.\nSobresanación (overheal): curar más de lo que le falta a alguien. Lo que sobra es maná perdido.\nBanda (raid): un grupo más grande que en un calabozo, contra jefes más grandes.\nInstancia: un sitio donde solo entra tu grupo, como un calabozo, una banda o un abismo.\nLo malo: zonas dañinas en el suelo, como fuego. Sal de ahí.\nTeclas: MH las escribe aquí abreviadas, como el juego: s-3 es Mayús+3 (Shift+3), c- es Ctrl.",
	ACCOUNT_WEEKLY_DELVER_ALTS_FMT = "Se busca surcabismos, pendiente en alts: %d (%s)",
