	AGGRO_CHECK_FOOTER = "Dónde encontrarlos y qué hacen: Codex > Calabozos y M+ > Aggro.",
	AHSHOP_TIP_BODY = "Abre ¿Listo para la banda? (consumibles, encantamientos, gemas) con una pestaña Profesión para tus recetas. Haz clic en una fila para buscar en la Casa de Subastas, o envía todo a Auctionator. También: /mh ready. Puedes ocultar este botón en Configuración.",
	ALERT_HELP_HEADER = "Ayuda extra durante los calabozos",
