	ALT_COL_KEYS_HINT = "Restored Coffer Keys en este personaje.\nPor qué: cada una abre un Bountiful Coffer al final de un abismo abundante.\nReinicio: nunca; esperan hasta que las uses.",
	ALT_COL_VAULT = "Gran bóveda",
